def prepare(stripe, world, ctx):
    old = None
    for p in world["prices"]:
        if p["id"] == OLD_PRO_MONTHLY:
            old = p
            break
    product = old["product"]

    new_price = None
    existing = stripe.Price.list(product=product, active=True, limit=100)
    for p in existing["data"]:
        rec = p["recurring"]
        if (p["unit_amount"] == 2900 and p["currency"] == old["currency"]
                and rec and rec["interval"] == "month"
                and rec["interval_count"] == 1
                and p["id"] != OLD_PRO_MONTHLY):
            new_price = p["id"]
            break

    if new_price is None:
        created = stripe.Price.create(
            product=product,
            unit_amount=2900,
            currency=old["currency"],
            recurring={"interval": "month", "interval_count": 1},
            nickname="Pro monthly $29",
        )
        new_price = created["id"]

    return {"new_price": new_price}


def migrate(stripe, sub, world, prepared, ctx):
    s = stripe.Subscription.retrieve(sub["live_id"])
    new_price = prepared["new_price"]

    if s["cancel_at_period_end"]:
        return {"action": "skipped", "why": "cancelling at period end"}

    target = None
    for it in s["items"]["data"]:
        pid = it["price"]["id"]
        if pid == new_price:
            return {"action": "skipped", "why": "already on new price"}
        if pid == OLD_PRO_MONTHLY:
            target = it
    if target is None:
        return {"action": "skipped", "why": "not a Pro monthly subscription"}

    if s["status"] not in ("active", "trialing"):
        return {"action": "skipped", "why": "status " + str(s["status"])}

    stripe.Subscription.modify(
        s["id"],
        items=[{"id": target["id"], "price": new_price}],
        proration_behavior="none",
    )
    return {
        "action": "swapped",
        "from": OLD_PRO_MONTHLY,
        "to": new_price,
        "status": s["status"],
    }

