def migrate(stripe, sub, world, prepared, ctx):
    old_price = prepared["old_price"]
    new_price = prepared["new_price"]

    if not any(i["price"] == old_price for i in sub["items"]):
        return {"action": "skipped", "why": "not Pro monthly"}
    if sub.get("cancel_at_period_end"):
        return {"action": "skipped", "why": "cancelling at period end; left untouched"}

    s = stripe.Subscription.retrieve(sub["live_id"])
    items = s["items"]["data"]
    if len(items) != 1 or items[0]["price"]["id"] != old_price:
        return {"action": "skipped", "why": "unexpected items"}
    item = items[0]
    qty = item["quantity"]

    if s["status"] == "trialing":
        # No charge is possible during trial; swap in place, trial end preserved.
        stripe.Subscription.modify(
            s["id"],
            items=[{"id": item["id"], "price": new_price}],
            proration_behavior="none",
        )
        return {"action": "swapped_in_trial", "trial_end": s["trial_end"]}

    sched = stripe.SubscriptionSchedule.create(from_subscription=s["id"])
    phase0 = sched["phases"][0]
    stripe.SubscriptionSchedule.modify(
        sched["id"],
        end_behavior="release",
        proration_behavior="none",
        phases=[
            {
                "items": [{"price": old_price, "quantity": qty}],
                "start_date": phase0["start_date"],
                "end_date": phase0["end_date"],
            },
            {
                "items": [{"price": new_price, "quantity": qty}],
                "iterations": 1,
            },
        ],
    )
    return {"action": "scheduled", "switch_at": phase0["end_date"], "schedule": sched["id"]}

