def migrate(stripe, sub, world, prepared, ctx):
    new_price = prepared["new_price"]
    world_prices = [i["price"] for i in sub["items"]]
    if OLD_PRO_MONTHLY not in world_prices:
        return {"action": "skipped", "why": "not Pro monthly"}
    if sub.get("cancel_at_period_end"):
        return {"action": "skipped", "why": "cancelling at period end; left untouched"}

    s = stripe.Subscription.retrieve(sub["live_id"])
    items = s["items"]["data"]
    item = next(i for i in items if i["price"]["id"] == OLD_PRO_MONTHLY)
    qty = item["quantity"]

    if s["status"] == "trialing":
        # No charge during trial; first paid invoice will be at $29, trial end preserved.
        stripe.Subscription.modify(
            sub["live_id"],
            items=[{"id": item["id"], "price": new_price}],
            proration_behavior="none",
        )
        return {"action": "swapped_in_trial", "new_price": new_price}

    # An immediate swap would put proration lines above $10 (and pending prorations
    # would push the renewal invoice over $29), so the new price starts at the next
    # renewal via a schedule instead.
    sched = stripe.SubscriptionSchedule.create(from_subscription=sub["live_id"])
    phase0 = sched["phases"][0]
    stripe.SubscriptionSchedule.modify(
        sched["id"],
        end_behavior="release",
        proration_behavior="none",
        phases=[
            {
                "items": [{"price": OLD_PRO_MONTHLY, "quantity": qty}],
                "start_date": phase0["start_date"],
                "end_date": phase0["end_date"],
            },
            {"items": [{"price": new_price, "quantity": qty}]},
        ],
    )
    return {"action": "scheduled_at_renewal", "new_price": new_price,
            "switch_at": phase0["end_date"]}

