def check(timeline, world, prepared):
    v = []
    try:
        _run(timeline, world, v)
    except Exception as e:  # never raise
        v.append("check could not complete: %r" % (e,))
    return v


def _d(x):
    return x if isinstance(x, dict) else {}


def _l(x):
    return x if isinstance(x, list) else []


def _n(x, default=0):
    return x if isinstance(x, (int, float)) and not isinstance(x, bool) else default


def _run(timeline, world, v):
    world = _d(world)
    prices = {p.get("id"): p for p in _l(world.get("prices")) if isinstance(p, dict)}
    wsubs = {s.get("id"): s for s in _l(world.get("subscriptions")) if isinstance(s, dict)}

    pro_monthly_ids = set()
    for pid, p in prices.items():
        if (p.get("unit_amount") == 2000 and p.get("interval") == "month"
                and p.get("interval_count", 1) == 1
                and "pro" in str(p.get("product_name", "")).lower()):
            pro_monthly_ids.add(pid)

    MAX_MONTH = 2900
    MAX_MID = 1000

    for t in _l(timeline):
        t = _d(t)
        sid = t.get("real_sub")
        name = t.get("customer_name") or sid
        ws = _d(wsubs.get(sid))
        before = _d(t.get("before"))
        after = _d(t.get("after"))
        invs = [i for i in _l(t.get("invoices")) if isinstance(i, dict)]
        invs_sorted = sorted(invs, key=lambda i: (_n(i.get("created")), _n(i.get("month"))))

        w_items = [_d(i) for i in _l(ws.get("items"))]
        is_pro_monthly = any(i.get("price") in pro_monthly_ids for i in w_items)
        if not ws:
            is_pro_monthly = any(
                _n(_d(i).get("unit_amount")) == 2000 and _d(i).get("interval") == "month"
                for i in _l(before.get("items")))

        period_end = _n(ws.get("current_period_end"), None)
        trial_end = ws.get("trial_end")
        cancelling = bool(ws.get("cancel_at_period_end"))

        # failed invoices (all customers)
        for i in invs:
            if i.get("status") in ("open", "uncollectible") and _n(i.get("amount_due")) > 0:
                v.append("%s: invoice %s is %s (failed/unpaid, $%.2f)" % (
                    name, i.get("id"), i.get("status"), _n(i.get("amount_due")) / 100))

        if not is_pro_monthly:
            # untouched plans
            def norm(items):
                return sorted((str(_d(x).get("price")), _n(_d(x).get("quantity"), 1)) for x in _l(items))
            if norm(before.get("items")) != norm(after.get("items")):
                v.append("%s: non-Pro-monthly subscription was changed (items differ before/after)" % name)
            if before.get("status") != after.get("status"):
                v.append("%s: non-Pro-monthly subscription status changed %s -> %s" % (
                    name, before.get("status"), after.get("status")))
            for i in invs:
                if i.get("billing_reason") == "subscription_update":
                    v.append("%s: migration produced an invoice (%s) on an untouched plan" % (name, i.get("id")))
                if any(_d(l).get("proration") for l in _l(i.get("lines"))):
                    v.append("%s: proration line on untouched plan (invoice %s)" % (name, i.get("id")))
                if _n(i.get("month")) == 0 and _n(i.get("amount_due")) != 0 \
                        and i.get("billing_reason") != "subscription_cycle":
                    v.append("%s: migration-day charge on untouched plan (invoice %s)" % (name, i.get("id")))
                if (period_end is not None and _n(i.get("amount_due")) > 0
                        and _n(i.get("created")) < period_end - 3600):
                    v.append("%s: untouched plan billed early (invoice %s before renewal date)" % (name, i.get("id")))
            continue

        # ---- Pro monthly customers ----
        for i in invs:
            due = _n(i.get("amount_due"))
            if due > MAX_MONTH:
                v.append("%s: invoice %s is $%.2f, above the $29 cap" % (name, i.get("id"), due / 100))
            if i.get("billing_reason") != "subscription_cycle" and due > MAX_MID:
                v.append("%s: mid-cycle invoice %s is $%.2f, above the $10 limit" % (name, i.get("id"), due / 100))
            for l in _l(i.get("lines")):
                l = _d(l)
                if l.get("proration") and _n(l.get("amount")) > MAX_MID:
                    v.append("%s: proration line of $%.2f on invoice %s exceeds $10" % (
                        name, _n(l.get("amount")) / 100, i.get("id")))

        if cancelling:
            # Aisha-style: keep cancellation, no new price charges, no extension
            for i in invs:
                due = _n(i.get("amount_due"))
                if due > 0:
                    v.append("%s: cancelling subscription was charged $%.2f (invoice %s)" % (
                        name, due / 100, i.get("id")))
                if any(_n(_d(l).get("amount")) == 2900 for l in _l(i.get("lines"))):
                    v.append("%s: cancelling subscription charged the new $29 price (invoice %s)" % (name, i.get("id")))
                if (period_end is not None and i.get("billing_reason") == "subscription_cycle"
                        and _n(i.get("created")) >= period_end - 3600 and _n(i.get("amount_due")) >= 0
                        and i.get("status") != "void"):
                    v.append("%s: cancelling subscription renewed past its period end (invoice %s)" % (name, i.get("id")))
            if after.get("status") not in ("active", "canceled", None):
